<?php namespace App\Filament\Pages;use Filament\Pages\Page;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Schema;
class AcademicOfficeDashboard extends Page{protected static ?string $navigationIcon='heroicon-o-office-building';protected static ?string $navigationLabel='Обзор учебной части';protected static ?string $navigationGroup='Учебная часть';protected static ?int $navigationSort=1;protected static string $view='filament.pages.academic-office-dashboard';public array $stats=[],$orders=[];public function mount():void{$p=request()->attributes->get('academic_period');$pid=$p?->id;$this->stats=['students'=>Schema::hasTable('students')?DB::table('students')->where('status','active')->count():0,'groups'=>Schema::hasTable('study_groups')?DB::table('study_groups')->where('active',1)->count():0,'debts'=>$pid&&Schema::hasTable('attestation_attempts')?DB::table('attestation_attempts as a')->join('attestation_sheets as sh','sh.id','=','a.attestation_sheet_id')->where('sh.academic_period_id',$pid)->where('a.passed',0)->count():0,'sheets'=>$pid&&Schema::hasTable('attestation_sheets')?DB::table('attestation_sheets')->where('academic_period_id',$pid)->where('status','open')->count():0,'gia'=>$pid&&Schema::hasTable('gia_campaigns')?DB::table('gia_campaigns')->where('academic_period_id',$pid)->count():0,'movements'=>$pid&&Schema::hasTable('student_movements')?DB::table('student_movements')->where('academic_period_id',$pid)->count():0];$this->orders=$pid&&Schema::hasTable('academic_orders')?DB::table('academic_orders')->where('academic_period_id',$pid)->orderByDesc('order_date')->limit(8)->get()->map(fn($x)=>(array)$x)->all():[];}public static function canAccess():bool{$u=auth()->user();return $u&&($u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('head_academic')||$u->canDo('students.manage'));}}